suppressPackageStartupMessages(library(massdataset));dir.create('test-output/annotation-fixture',recursive=TRUE,showWarnings=FALSE)
e<-new.env();load(file.path(Sys.getenv('LIPIDFLOW_TEST_RESOURCES', unset='.'),'backend/databases/msdial_lipid_pos_db.rda'),e);d<-e[[ls(e)[1]]];idx<-which(vapply(d@spectra.data$Spectra.positive,function(s)nrow(s[[1]])>=6,logical(1)))[1:2];ids<-names(d@spectra.data$Spectra.positive)[idx];d@spectra.info<-d@spectra.info[match(ids,d@spectra.info$Lab.ID),];d@spectra.data$Spectra.positive<-d@spectra.data$Spectra.positive[ids];d@spectra.data$Spectra.negative<-list();save(d,file='test-output/annotation-fixture/database.rda')
print(str(d@spectra.data$Spectra.positive[[1]]))
obj<-create_mass_dataset(expression_data=data.frame(S1=c(1000,2000),S2=c(1500,3000),row.names=c("f1","f2")),sample_info=data.frame(sample_id=c('S1','S2'),group=c('A','B'),class=c('Subject','Subject'),injection.order=1:2),variable_info=data.frame(variable_id=c('f1','f2'),mz=d@spectra.info$mz,rt=c(100,200)))
save(obj,file='test-output/annotation-fixture/peaks.rda')
f<-'test-output/annotation-fixture/spectra.mgf';cat('',file=f)
for(i in 1:2){sp<-d@spectra.data$Spectra.positive[[i]][[1]];cat('BEGIN IONS\nTITLE=fixture_',i,'\nPEPMASS=',d@spectra.info$mz[i],'\nRTINSECONDS=',i*100,'\nCHARGE=1+\n',sep='',file=f,append=TRUE);write.table(sp[,1:2],f,row.names=FALSE,col.names=FALSE,quote=FALSE,append=TRUE);cat('END IONS\n',file=f,append=TRUE)}
